fn is_non_prime(n: u64) -> bool {
    // Handle n = 2 separately (smallest prime)
    if n == 2 {
        return false;
    }
    
    // Check if n is even (except 2 which we already handled)
    if n % 2 == 0 {
        return true;
    }
    
    // Check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    for k in (3..=limit).step_by(2) {
        if n % k == 0 {
            return true;
        }
    }
    
    // If no divisor found, n is prime
    false
}